/* Set the restaurant's WhatsApp number here: international digits only, no +. */
const WHATSAPP_NUMBER = "";
const CART_KEY = 'lalla-mama-cart-v1';
const products = new Map(MENU_DATA.flatMap(c => c.items.map(p => [p.id,p])));
const $ = s => document.querySelector(s);
const escapeHTML = s => String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money = n => `${n} DH`;
const paths={cart:'M2 3h3l3 12h12l3-9H6 M9 20h.01 M19 20h.01',breakfast:'M3 14h18v6H3z M6 14V7a3 3 0 0 1 6 0v7 M12 7a3 3 0 0 1 6 0v7',tea:'M3 10h14v6a5 5 0 0 1-5 5H8a5 5 0 0 1-5-5z M17 11h2a3 3 0 0 1 0 6h-2 M7 2v4 M12 2v4',salad:'M2 13h20a10 10 0 0 1-20 0z M5 13C0 5 8 4 9 9 M9 13c-2-9 7-13 7-4 M15 13c0-8 9-8 6 0',soup:'M2 12h20a10 10 0 0 1-20 0z M7 8c-4-3 3-3 0-7 M13 8c-4-3 3-3 0-7 M19 8c-4-3 3-3 0-7',dish:'M2 18h20 M4 16a8 8 0 0 1 16 0z M12 8V5 M10 4h4',tagine:'M2 19h20l-2 3H4z M4 17 11 5h2l7 12z M10 3h4',meat:'M4 13c-5-8 7-13 11-8s-1 9-5 9l-4 7-3-2 4-7',grill:'M3 21 21 3 M6 13l5 5 M9 10l5 5 M12 7l5 5 M15 4l5 5',sandwich:'M3 10c0-10 18-10 18 0z M2 14h20 M3 18h18l-2 3H5z M7 6h.01 M12 5h.01 M17 6h.01',wrap:'M5 3h14l-3 19H9z M5 8h14 M8 12l8 4',dessert:'M5 10h14l-2 12H7z M5 10c-5-6 4-8 5-5-1-7 11-5 8 1 5-1 6 5 1 4 M10 13v6 M14 13v6',drink:'M4 3h16l-3 19H7z M5 8h14 M12 18l3-17h5'};
function icon(name){return `<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.dish}"/></svg>`;}
document.querySelectorAll('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon));
$('#categories').innerHTML=MENU_DATA.map((c,i)=>`<a class="category-link ${i===0?'active':''}" href="#${c.id}" ${i===0?'aria-current="true"':''}>${icon(c.icon)}<span>${escapeHTML(c.name)}</span></a>`).join('');
$('#menu').innerHTML=MENU_DATA.map((c,i)=>`<section class="menu-section" id="${c.id}" aria-labelledby="heading-${i}"><figure class="category-hero"><img src="${c.image}" width="512" height="256" ${i?'loading="lazy"':'fetchpriority="high"'} alt="${escapeHTML(c.name)} — inspiration de la cuisine marocaine"><figcaption><div class="brush">${icon(c.icon)}<h2 id="heading-${i}">${escapeHTML(c.name)}</h2></div><span class="category-arabic" lang="ar" dir="rtl">${escapeHTML(c.arabic)}</span></figcaption></figure><div class="products">${c.items.map(p=>`<article class="product"><div class="product-info"><h3>${escapeHTML(p.name)}</h3><span class="product-price">${money(p.price)}</span>${p.description?`<p class="description">${escapeHTML(p.description)}</p>`:''}</div><button class="primary" data-add="${p.id}" aria-label="Ajouter ${escapeHTML(p.name)} au panier">+ Ajouter</button></article>`).join('')}</div></section>`).join('');
let cart={};
try{const saved=JSON.parse(localStorage.getItem(CART_KEY)||'{}');if(saved&&typeof saved==='object'&&!Array.isArray(saved))for(const [id,q] of Object.entries(saved))if(products.has(id)&&Number.isSafeInteger(q)&&q>0)cart[id]=Math.min(q,999);}catch{}
function entries(){return Object.entries(cart).map(([id,quantity])=>({...products.get(id),quantity}));}
function totals(){return entries().reduce((a,p)=>({count:a.count+p.quantity,total:a.total+p.price*p.quantity}),{count:0,total:0});}
let toastTimer;
function animateAddToCart(button){
 const target=$('.footer-icon').getBoundingClientRect().width?$('.footer-icon'):$('.cart-bar .primary');
 const pulse=()=>{target.getAnimations().forEach(a=>a.cancel());if(!matchMedia('(prefers-reduced-motion: reduce)').matches)target.animate([{transform:'scale(1)'},{transform:'scale(1.16)',filter:'drop-shadow(0 0 12px #ff8300)'},{transform:'scale(1)'}],{duration:360,easing:'ease-out'});};
 if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;
 const from=button.getBoundingClientRect(),to=target.getBoundingClientRect();
 const startX=from.left+from.width/2-22,startY=from.top+from.height/2-22;
 const dx=to.left+to.width/2-22-startX,dy=to.top+to.height/2-22-startY;
 const particle=document.createElement('span');particle.className='flying-cart';particle.setAttribute('aria-hidden','true');particle.innerHTML=icon('cart');particle.style.left=`${startX}px`;particle.style.top=`${startY}px`;document.body.append(particle);
 const flight=particle.animate([{transform:'translate(0,0) scale(1)',opacity:1},{transform:`translate(${dx*.35}px,${Math.min(-65,dy*.3-65)}px) scale(1.15)`,opacity:1,offset:.35},{transform:`translate(${dx}px,${dy}px) scale(.35)`,opacity:.15}],{duration:650,easing:'cubic-bezier(.3,.05,.65,1)',fill:'forwards'});
 flight.finished.then(()=>{particle.remove();pulse();}).catch(()=>particle.remove());
}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),2000);}
function updateCart(render=true){const {count,total}=totals();document.querySelectorAll('.cart-count').forEach(el=>el.textContent=count);$('#article-count').textContent=`${count} article${count===1?'':'s'}`;$('#cart-total').textContent=money(total);$('#sheet-count').textContent=`${count} article${count===1?'':'s'}`;$('#sheet-total').textContent=money(total);try{localStorage.setItem(CART_KEY,JSON.stringify(cart));}catch{toast('La sauvegarde du panier est indisponible.');}if(render)renderCart();$('#checkout').disabled=!count||!/^\d{8,15}$/.test(WHATSAPP_NUMBER);$('#order-form').hidden=!count;}
function renderCart(){const rows=entries();$('#cart-items').innerHTML=rows.length?rows.map(p=>`<article class="cart-item"><div><h3>${escapeHTML(p.name)}</h3><p>${money(p.price)} / unité</p></div><div class="quantity"><button type="button" data-minus="${p.id}" aria-label="Diminuer ${escapeHTML(p.name)}">−</button><output aria-label="Quantité">${p.quantity}</output><button type="button" data-plus="${p.id}" aria-label="Augmenter ${escapeHTML(p.name)}" ${p.quantity===999?'disabled':''}>+</button></div><button type="button" class="remove" data-remove="${p.id}" aria-label="Retirer ${escapeHTML(p.name)}">Retirer</button><strong class="line-total">${money(p.price*p.quantity)}</strong></article>`).join(''):`<div class="empty">${icon('cart')}<h3>Votre panier vous attend</h3><p>Ajoutez vos plats préférés pour commencer.</p><button type="button" class="primary" data-continue>Découvrir le menu</button></div>`;}
document.addEventListener('click',e=>{const add=e.target.closest('[data-add]');if(add){const id=add.dataset.add;if((cart[id]||0)>=999){toast('Quantité maximale : 999');return;}cart[id]=(cart[id]||0)+1;updateCart();animateAddToCart(add);toast('✓ Ajouté au panier');document.querySelectorAll('.cart-count').forEach(el=>{el.classList.remove('pop');void el.offsetWidth;el.classList.add('pop');});}const change=e.target.closest('[data-plus],[data-minus],[data-remove]');if(change){const id=change.dataset.plus||change.dataset.minus||change.dataset.remove;if(!cart[id])return;if(change.hasAttribute('data-remove'))delete cart[id];else{cart[id]+=change.hasAttribute('data-plus')?1:-1;if(cart[id]<=0)delete cart[id];}const action=change.hasAttribute('data-plus')?'data-plus':change.hasAttribute('data-minus')?'data-minus':'data-remove';updateCart();const next=$(`[${action}="${id}"]`)||$('#close-cart');next.focus();}if(e.target.closest('[data-continue]'))closeCart();});
const dialog=$('#cart-dialog');let previousFocus;
function openCart(){previousFocus=document.activeElement;updateCart();dialog.showModal();document.body.style.overflow='hidden';$('#close-cart').focus();}
function closeCart(){dialog.close();}
document.querySelectorAll('.open-cart').forEach(b=>b.addEventListener('click',openCart));$('#close-cart').addEventListener('click',closeCart);dialog.addEventListener('close',()=>{document.body.style.overflow='';previousFocus?.focus();});dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeCart();}});
const form=$('#order-form');
function updateFields(){const type=form.elements.type.value;$('#table-field').hidden=type!=='Sur place';form.elements.table.required=type==='Sur place';$('#address-field').hidden=type!=='Livraison';form.elements.address.required=type==='Livraison';}
form.elements.type.addEventListener('change',updateFields);
function buildWhatsAppOrder(order,customerInfo){const lines=['🍽️ NOUVELLE COMMANDE — LALLA MAMA','',`👤 Client : ${customerInfo.customer}`,`📍 Type : ${customerInfo.type}`];if(customerInfo.type==='Sur place')lines.push(`🪑 Table : ${customerInfo.table}`);if(customerInfo.type==='Livraison')lines.push(`📍 Adresse : ${customerInfo.address}`);lines.push('','🛒 COMMANDE :','');for(const p of order)lines.push(`${p.quantity} × ${p.name}`,`${p.price} DH × ${p.quantity} = ${p.price*p.quantity} DH`,'');lines.push('------------------------',`TOTAL : ${order.reduce((s,p)=>s+p.price*p.quantity,0)} DH`,'------------------------');if(customerInfo.notes)lines.push('',`📝 Notes : ${customerInfo.notes}`);lines.push('','Merci !');return lines.join('\n');}
form.addEventListener('submit',e=>{e.preventDefault();if(!totals().count||!/^\d{8,15}$/.test(WHATSAPP_NUMBER))return;for(const field of [form.elements.customer,form.elements.table,form.elements.address]){field.setCustomValidity(field.required&&!field.value.trim()?'Veuillez renseigner ce champ.':'');}if(!form.reportValidity())return;const info=Object.fromEntries(new FormData(form));for(const k in info)info[k]=info[k].trim();window.open(`https://wa.me/${WHATSAPP_NUMBER}?text=${encodeURIComponent(buildWhatsAppOrder(entries(),info))}`,'_blank','noopener,noreferrer');});
form.addEventListener('input',e=>e.target.setCustomValidity?.(''));
$('#configuration-message').textContent=WHATSAPP_NUMBER?'':'Les commandes WhatsApp ne sont pas encore disponibles. Le numéro du restaurant doit être configuré.';
$('#menu-toggle').addEventListener('click',()=>{const nav=$('#categories');const expanded=$('#menu-toggle').getAttribute('aria-expanded')==='true';$('#menu-toggle').setAttribute('aria-expanded',String(!expanded));nav.scrollIntoView({behavior:'smooth',block:'start'});nav.querySelector('a').focus({preventScroll:true});});
let scheduled=false;
function highlight(){scheduled=false;const sections=[...document.querySelectorAll('.menu-section')];let active=sections[0];for(const s of sections)if(s.getBoundingClientRect().top<=150)active=s;document.querySelectorAll('.category-link').forEach(a=>{const yes=a.hash===`#${active.id}`;a.classList.toggle('active',yes);if(yes){a.setAttribute('aria-current','true');const nav=$('#categories');if(a.offsetLeft<nav.scrollLeft||a.offsetLeft+a.offsetWidth>nav.scrollLeft+nav.clientWidth)nav.scrollTo({left:a.offsetLeft-nav.clientWidth/2+a.offsetWidth/2,behavior:'smooth'});}else a.removeAttribute('aria-current');});}
window.addEventListener('scroll',()=>{if(!scheduled){scheduled=true;requestAnimationFrame(highlight);}},{passive:true});
updateFields();updateCart();
